graphql.document:
query ProjectLabels($fullPath: ID!, $first: Int) {
  project(fullPath: $fullPath) {
    labels(first: $first, includeAncestorGroups: true) {
      nodes { id title color textColor description }
      pageInfo { hasNextPage endCursor }
    }
  }
}

query ProjectMilestones($fullPath: ID!, $first: Int) {
  project(fullPath: $fullPath) {
    milestones(first: $first, includeAncestors: true, state: active) {
      nodes { id iid title state dueDate startDate webPath }
      pageInfo { hasNextPage endCursor }
    }
  }
}

query MergeRequestList($fullPath: ID!, $state: MergeRequestState, $first: Int, $after: String) {
  project(fullPath: $fullPath) {
    mergeRequests(state: $state, sort: UPDATED_DESC, first: $first, after: $after) {
      pageInfo { hasNextPage endCursor }
      nodes {
        iid id title draft webUrl updatedAt userNotesCount mergeStatusEnum
        author { username }
        labels { nodes { title color } }
        approved approvedBy { nodes { username } }
        reviewers { nodes { username } }
        headPipeline { status }
        diffStatsSummary { additions deletions fileCount }
      }
    }
  }
}

query MergeRequestThreads($fullPath: ID!, $iid: String!, $first: Int) {
  project(fullPath: $fullPath) {
    mergeRequest(iid: $iid) {
      iid
      diffRefs { baseSha headSha startSha }
      discussions(first: $first) {
        nodes {
          id resolved resolvable
          notes {
            nodes {
              id body system internal createdAt updatedAt
              author { username name }
              position { positionType newPath newLine oldPath oldLine diffRefs { headSha } }
            }
          }
        }
        pageInfo { hasNextPage endCursor }
      }
    }
  }
}

query PipelineJobs($fullPath: ID!, $iid: ID!, $first: Int) {
  project(fullPath: $fullPath) {
    pipeline(iid: $iid) {
      iid status
      jobs(first: $first) {
        nodes {
          id name status stage { name } allowFailure retryable duration startedAt finishedAt webPath
          trace { htmlSummary }
        }
        pageInfo { hasNextPage endCursor }
      }
    }
  }
}
